:root {
  color-scheme: dark light;
  font: 14px/1.5 system-ui, sans-serif;
  color: var(--primary-text-color, #e8eef5);
  background: var(--primary-background-color, #101820);
  --accent: var(--accent-color, #29cdbb);
  --panel: var(--card-background-color, #19252b);
  --surface: var(--primary-background-color, #101820);
  --border: var(--divider-color, #34444c);
  --muted: var(--secondary-text-color, #afbdc6);
}
* { box-sizing: border-box; }
body { margin: 0; padding: 20px; }
button, input, select, textarea { font: inherit; }
button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, label.button:focus-within { outline: 2px solid var(--accent); outline-offset: 2px; }
.layout { width: min(1400px, 100%); margin: 0 auto; }
.topbar { display: flex; justify-content: space-between; align-items: start; gap: 20px; margin-bottom: 16px; }
.eyebrow { margin: 0 0 3px; color: var(--accent); font-size: .72rem; font-weight: 750; letter-spacing: .09em; }
h1, h2, p { margin-top: 0; }
h1 { margin-bottom: 5px; font-size: clamp(1.45rem, 3vw, 1.9rem); }
h2 { margin: 0; font-size: 1.05rem; }
.intro { max-width: 70ch; margin: 0; color: var(--muted); }
.language-control { display: grid; gap: 4px; min-width: 130px; color: var(--muted); font-size: .82rem; }
.workspace { display: grid; grid-template-columns: minmax(200px, .76fr) minmax(310px, 1.12fr) minmax(270px, .92fr); align-items: start; gap: 12px; }
.panel { min-width: 0; padding: 16px; border: 1px solid var(--border); border-radius: 11px; background: var(--panel); }
.section-heading { display: flex; justify-content: space-between; align-items: center; gap: 10px; margin-bottom: 12px; }
.count, .prefix { color: var(--accent); font-weight: 700; }
.icon-list { display: grid; gap: 6px; max-height: 380px; margin: 10px 0; overflow: auto; }
.icon-entry { display: flex; align-items: center; gap: 10px; width: 100%; min-width: 0; padding: 8px 10px; border: 1px solid transparent; border-radius: 8px; background: transparent; color: inherit; cursor: pointer; text-align: left; }
.icon-entry:hover { border-color: var(--border); }
.icon-entry.is-active { border-color: var(--accent); background: color-mix(in srgb, var(--accent) 12%, transparent); }
.icon-entry svg { flex: 0 0 auto; fill: currentColor; color: var(--accent); }
.icon-entry span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.empty-list { margin: 10px 2px; color: var(--muted); }
label:not(.button) { display: block; margin: 10px 0 5px; font-weight: 650; }
input, select, textarea { width: 100%; min-width: 0; padding: 8px 10px; border: 1px solid var(--border); border-radius: 7px; color: inherit; background: var(--surface); }
textarea { min-height: 145px; resize: vertical; font: 12px/1.5 ui-monospace, Consolas, monospace; }
input[type="search"] { margin-top: 0; }
.name-row { display: flex; align-items: center; gap: 7px; }
.prefix { flex: 0 0 auto; }
.field-hint { margin: 4px 0 10px; color: var(--muted); font-size: .8rem; }
.button { display: inline-flex; align-items: center; justify-content: center; min-height: 36px; padding: 7px 10px; border: 1px solid var(--border); border-radius: 7px; color: inherit; cursor: pointer; text-align: center; text-decoration: none; }
.button:hover:not(:disabled) { border-color: var(--accent); }
.button:disabled { opacity: .5; cursor: not-allowed; }
.primary { border-color: var(--accent); background: var(--accent); color: #05201e; font-weight: 700; }
.secondary { background: transparent; }
.danger { color: var(--error-color, #f28b82); }
.full-width { width: 100%; margin-top: 7px; }
.file-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; margin-top: 10px; }
.file-actions .button { padding-inline: 6px; font-size: .84rem; }
.status { color: var(--accent); font-size: .8rem; text-align: right; }
.preview { display: grid; place-items: center; min-height: 210px; padding: 20px; border: 1px dashed var(--border); border-radius: 9px; background: var(--surface); }
.preview[hidden], .image-preview[hidden] { display: none; }
.preview svg { width: 120px; height: 120px; fill: currentColor; color: var(--accent); }
.image-preview { display: grid; gap: 8px; margin-top: 8px; }
.image-preview img { display: block; width: 100%; max-height: 300px; object-fit: contain; border-radius: 7px; background: var(--surface); }
.usage-label { margin: 14px 0 5px; font-weight: 650; }
.usage-row { display: flex; gap: 6px; }
.usage-row input { flex: 1; font: 12px ui-monospace, Consolas, monospace; }
.usage-row .button { flex: 0 0 auto; }
.notice { margin: 10px 0 0; padding: 9px 10px; border-left: 3px solid var(--accent); color: var(--muted); font-size: .8rem; }
.notice.compact { border-left-color: var(--border); }
.visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; clip-path: inset(50%); }
@media (max-width: 900px) { .workspace { grid-template-columns: minmax(190px, .7fr) minmax(280px, 1fr); } .preview-pane { grid-column: 1 / -1; } }
@media (max-width: 600px) { body { padding: 12px; } .topbar { flex-direction: column; } .language-control { width: 100%; } .workspace { grid-template-columns: 1fr; } .preview-pane { grid-column: auto; } .panel { padding: 13px; } }

